const visual = {
  prepare: function (input) {
    return [
      { kind: 'text', payload: 'F(x) = F0(1 - x/h)' },
      { kind: 'text', payload: 'x' },
      { kind: 'text', payload: 'F' },
      { kind: 'text', payload: '0' },
      { kind: 'text', payload: 'h' },
      { kind: 'text', payload: 'h/2' },
      { kind: 'text', payload: 'F0' },
      { kind: 'text', payload: 'F0/2' },
      { kind: 'text', payload: 'W = (3/8) F0 h' },
      { kind: 'text', payload: 'W/(F0 h) = 3/8 = 0.375' }
    ];
  },
  render: function (input, metrics) {
    var W = input.viewport.widthDu;
    var H = input.viewport.heightDu;
    var left = Math.max(70, W * 0.13);
    var right = Math.max(46, W * 0.09);
    var top = Math.max(46, H * 0.11);
    var bottom = Math.max(64, H * 0.15);
    var plotW = W - left - right;
    if (plotW < 60) { plotW = 60; }
    var y0 = H - bottom;
    var plotH = y0 - top;
    if (plotH < 60) { plotH = 60; y0 = top + plotH; }
    var x0 = left;
    var xh = left + plotW;
    var cx = left + plotW / 2;
    var midY = top + plotH / 2;

    var axisX = visualSdk.arrow(x0, y0, xh + 20, y0, {});
    var axisY = visualSdk.arrow(x0, y0, x0, top - 22, {});
    var line = visualSdk.polyline([[x0, top], [xh, y0]]);
    var shade = [['M', x0, y0], ['L', x0, top], ['L', cx, midY], ['L', cx, y0], ['Z']];
    var edge = [['M', cx, y0], ['L', cx, midY]];
    var guide = [['M', x0, midY], ['L', cx, midY]];
    var tickXHalf = [['M', cx, y0], ['L', cx, y0 + 8]];
    var tickXH = [['M', xh, y0], ['L', xh, y0 + 8]];
    var tickYF0 = [['M', x0 - 8, top], ['L', x0, top]];
    var tickYHalf = [['M', x0 - 8, midY], ['L', x0, midY]];

    return {
      schemaVersion: 1,
      sceneId: 'f-x-linear',
      revision: input.revision,
      viewBox: { x: 0, y: 0, width: W, height: H },
      paths: [
        { id: 'shade', commands: shade },
        { id: 'guide', commands: guide },
        { id: 'axisX', commands: axisX },
        { id: 'axisY', commands: axisY },
        { id: 'line', commands: line },
        { id: 'edge', commands: edge },
        { id: 'tickXHalf', commands: tickXHalf },
        { id: 'tickXH', commands: tickXH },
        { id: 'tickYF0', commands: tickYF0 },
        { id: 'tickYHalf', commands: tickYHalf }
      ],
      root: {
        type: 'group',
        children: [
          { type: 'path', pathId: 'shade', fill: '#C9DDF3' },
          { type: 'path', pathId: 'guide', fill: '#8FA6C2', stroke: { width: 1, dash: [4, 4] } },
          { type: 'path', pathId: 'axisX', fill: '#26354A', stroke: { width: 2 } },
          { type: 'path', pathId: 'axisY', fill: '#26354A', stroke: { width: 2 } },
          { type: 'path', pathId: 'line', fill: '#1F4E79', stroke: { width: 2.5 } },
          { type: 'path', pathId: 'edge', fill: '#1F4E79', stroke: { width: 2 } },
          { type: 'path', pathId: 'tickXHalf', fill: '#26354A', stroke: { width: 1.5 } },
          { type: 'path', pathId: 'tickXH', fill: '#26354A', stroke: { width: 1.5 } },
          { type: 'path', pathId: 'tickYF0', fill: '#26354A', stroke: { width: 1.5 } },
          { type: 'path', pathId: 'tickYHalf', fill: '#26354A', stroke: { width: 1.5 } },
          { type: 'label', contentId: metrics[0].contentId, anchor: { x: left + plotW * 0.5, y: top + plotH * 0.12 }, hAlign: 'center', vAlign: 'bottom', color: '#1B2A3A' },
          { type: 'label', contentId: metrics[1].contentId, anchor: { x: xh + 22, y: y0 }, hAlign: 'left', vAlign: 'middle', color: '#1B2A3A' },
          { type: 'label', contentId: metrics[2].contentId, anchor: { x: x0 - 14, y: top - 18 }, hAlign: 'right', vAlign: 'middle', color: '#1B2A3A' },
          { type: 'label', contentId: metrics[3].contentId, anchor: { x: x0 - 8, y: y0 + 8 }, hAlign: 'right', vAlign: 'top', color: '#1B2A3A' },
          { type: 'label', contentId: metrics[4].contentId, anchor: { x: xh, y: y0 + 10 }, hAlign: 'center', vAlign: 'top', color: '#1B2A3A' },
          { type: 'label', contentId: metrics[5].contentId, anchor: { x: cx, y: y0 + 10 }, hAlign: 'center', vAlign: 'top', color: '#1B2A3A' },
          { type: 'label', contentId: metrics[6].contentId, anchor: { x: x0 - 12, y: top }, hAlign: 'right', vAlign: 'middle', color: '#1B2A3A' },
          { type: 'label', contentId: metrics[7].contentId, anchor: { x: x0 - 12, y: midY }, hAlign: 'right', vAlign: 'middle', color: '#1B2A3A' },
          { type: 'label', contentId: metrics[8].contentId, anchor: { x: left + plotW * (2 / 9), y: top + plotH * (11 / 18) }, hAlign: 'center', vAlign: 'middle', color: '#1B2A3A' },
          { type: 'label', contentId: metrics[9].contentId, anchor: { x: left + plotW * 0.25, y: y0 + 34 }, hAlign: 'center', vAlign: 'top', color: '#1B2A3A' }
        ]
      }
    };
  }
};
